urlset:
{% for post in posts %}

  {{ post.permalink | uriencode }}
  {% if post.updated %}
  {{ post.updated | formatDate }}
  {% elif post.date %}
  {{ post.date | formatDate }}
  {% endif %}
  monthly
  0.6

{% endfor %}

{# Homepage: omit lastmod — build-time dates are not a real content signal #}

  {{ config.url | uriencode }}
  daily
  1.0


{% for tag in tags %}

  {{ tag.permalink | uriencode }}
  weekly
  0.2

{% endfor %}

{% for cat in categories %}

  {{ cat.permalink | uriencode }}
  weekly
  0.2

{% endfor %}
